Lemma stream_of_prefix l N TF n :
  all_bytes l -> (n <= length l)%nat -> 0 <= TF <= 8 * Z.of_nat n -> 0 <= N < 2^TF ->
  (forall i, 0 <= i < Z.of_nat n -> Znth i l = byte_of N i) ->
  bytes_val l mod 2^TF = N.
Proof.
